import java.sql.*;import java.util.*;import java.nio.file.*;import com.alibaba.fastjson2.*;
/** Seed-derived read gates and actual committed-write/idempotency checks. */
public class LittleXGraphGate {
 static long[] counts(Connection c)throws Exception{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT (SELECT COUNT(*) FROM anchors WHERE kind='NodeAnchor' AND arch_type='Tweet'),(SELECT COUNT(*) FROM anchors WHERE kind='EdgeAnchor' AND arch_type='Follow'),(SELECT COALESCE(SUM(JSON_LENGTH(JSON_EXTRACT(props,'$.archetype.likes'))),0) FROM anchors WHERE kind='NodeAnchor' AND arch_type='Tweet')")){r.next();return new long[]{r.getLong(1),r.getLong(2),r.getLong(3)};}}
 static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}
 static void require(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 public static void main(String[]args)throws Exception{
 JSONArray in=JSON.parseArray(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));Path out=Paths.get(args[1]);Files.createDirectories(out);String url=System.getProperty("littlex.url");Class<?> impl=Class.forName(System.getProperty("littlex.implementation","LittleXFull"));java.lang.reflect.Method request=impl.getMethod("request",Connection.class,JSONObject.class);int passed=0;List<JSONObject>rows=new ArrayList<>();try(Connection c=DriverManager.getConnection(url,"root","")){
 Files.write(out.resolve("sql-mode.json"),LittleXSql.configureConnection(c).toJSONString().getBytes("UTF-8"));
 for(int i=0;i<in.size();i++){JSONObject x=in.getJSONObject(i);String op=x.getString("op");long[]before=counts(c);long start=System.nanoTime();JSONObject r=(JSONObject)request.invoke(null,c,x);double ms=(System.nanoTime()-start)/1e6;long commands=impl.getField("commands").getLong(null);long[]after=counts(c);JSONObject receipt=new JSONObject();JSONObject publicInput=new JSONObject(x);publicInput.remove("expected_seed_ids");receipt.put("input",publicInput);if(!op.startsWith("feed"))receipt.put("result",r);receipt.put("ms",ms);receipt.put("commands",commands);receipt.put("before",before);receipt.put("after",after);
 if(op.startsWith("feed")){JSONArray feed=r.getJSONArray("feed");List<String>ids=new ArrayList<>();for(int j=0;j<feed.size();j++)ids.add(feed.getJSONObject(j).getString("seed_id"));List<String>expected=x.getJSONArray("expected_seed_ids").toJavaList(String.class);if(op.equals("feed")){Collections.sort(ids);Collections.sort(expected);}require(ids.equals(expected),"seed-derived feed mismatch "+x.getString("username"));receipt.put("feed_count",ids.size());receipt.put("seed_identity_sha256",hex(java.security.MessageDigest.getInstance("SHA-256").digest(JSON.toJSONString(ids).getBytes("UTF-8"))));require(Arrays.equals(before,after),"read mutated state");}
 else {int index=op.equals("create_tweet")?0:op.equals("follow")?1:2;for(int j=0;j<3;j++)require(after[j]-before[j]==(j==index?1:0),"write state delta "+op);if(!op.equals("create_tweet")){JSONObject repeat=(JSONObject)request.invoke(null,c,x);require(Arrays.equals(after,counts(c)),"idempotent repeat changed state "+op);receipt.put("repeat_result",repeat);}else{JSONObject t=r.getJSONObject("tweet");require(t.getString("seed_id").equals(x.getString("seed_id"))&&t.getString("content").equals(x.getString("content"))&&t.getString("author_username").equals(x.getString("username")),"created content mismatch");}}
 receipt.put("passed",true);rows.add(receipt);passed++;Files.write(out.resolve("rows.json"),JSON.toJSONString(rows).getBytes("UTF-8"));}
 }JSONObject summary=new JSONObject();summary.put("passed",passed);summary.put("total",in.size());summary.put("status","PASS");Files.write(out.resolve("summary.json"),JSON.toJSONString(summary).getBytes("UTF-8"));System.out.println(summary);}
}
